        },
      } : {}),
    });
    state = nextState;

    if (terminalStatus !== undefined) {
      return {
        status: terminalStatus,
        state,
        tracePath: trace.path,
        iterations: iteration,
      };
    }
  }

  return {
    status: 'iteration_limit',
    state,
    tracePath: trace.path,
    iterations: maxIterations,
  };
}

