p='src/cli.ts';s=open(p).read().replace('function printApprovalProposal(context: ApprovalContext): void {','export function printApprovalProposal(context: ApprovalContext): void {').replace('  console.log(`Parameters: ${redactSensitiveText(JSON.stringify(proposal.input))}`);', '''  const parameters = JSON.stringify(proposal.input, (_key, value: unknown) =>
    typeof value === 'string' ? redactSensitiveText(value) : value);
  console.log(`Parameters: ${parameters}`);''');open(p,'w').write(s)
p='src/cli.test.ts';s=open(p).read().replace("import { describe, expect, it } from 'vitest';", "import { describe, expect, it, vi } from 'vitest';").replace('  parseApprovalChoice,','  parseApprovalChoice,\n  printApprovalProposal,').replace("import { mockEvaluation }", "import { buildWorkerContext } from './agents/context.js';\nimport { mockEvaluation }")
a=s.index("  it('parses user-only stop controls")
s=s[:a]+'''  it('prints parseable approval parameters when credential phrases end string values', () => {
    const workerContext = buildWorkerContext({
      ...state,
      evidence: {
        revision: 1,
        validationGeneration: 0,
        clarifications: [],
        findings: [{
          iteration: 1, source: 'read', paths: ['src/auth.ts'], excerpt: 'password=[REDACTED]',
        }],
        failures: [],
      },
    });
    const input = { root: '/repo', task: 'Fix password=fake-review-value', context: workerContext };
    const originalInput = structuredClone(input);
    const log = vi.spyOn(console, 'log').mockImplementation(() => {});
    try {
      printApprovalProposal({
        state,
        evaluation: mockEvaluation(),
        policy,
        proposal: { action: 'CALL_CODEX', tool: 'codex_cli', input },
        allowedAlternatives: ['CALL_CODEX', 'ASK_USER'],
      });
      const parameters = log.mock.calls.map(([line]) => line)
        .find((line): line is string => typeof line === 'string' && line.startsWith('Parameters: '));
      expect(parameters).toBeDefined();
      expect(parameters).not.toContain('fake-review-value');
      expect(JSON.parse(parameters!.slice('Parameters: '.length))).toEqual({
        ...input, task: 'Fix password=[REDACTED]',
      });
      expect(input).toEqual(originalInput);
    } finally {
      log.mockRestore();
    }
  });

''' +s[a:];open(p,'w').write(s)
PY
pnpm exec vitest run src/cli.test.ts

